//! Replays the Source oracle generated by apps/web behavior-inventory
//! `document-replace-oracle.test.ts` through the actual Rust surface.
use super::*;
use crate::{EditorType, plugins_group_b::decode_command, surface};

const ORACLE: &str = include_str!("replace-oracle.json");
const REPLACE_NAME: &str = "group-b.document-replace";
const STATS_NAME: &str = "group-b.document-stats";

fn editor(input: &Value) -> Result<Editor, Error> {
    let mut editor =
        surface::preset_builder_with_mode(EditorType::MarkdownSync, EditorMode::ViewAttached)
            .build()
            .expect("surface");
    let state = editor.parse_editor_state_str(&input.to_string())?;
    editor.set_editor_state(state, TagSet::default())?;
    Ok(editor)
}

fn path(view: StateRef<'_>, key: NodeKey) -> Value {
    let mut out = vec![];
    let mut current = key;
    while let Some(parent) = view.parent(current) {
        let index = view
            .children(parent)
            .position(|child| child == current)
            .expect("child of its parent");
        out.insert(0, Value::from(index));
        current = parent;
    }
    Value::from(out)
}

fn query_editor(editor: &Editor, name: &str, data: Value) -> Result<Value, Error> {
    Ok(surface::query(
        name,
        &data,
        editor.state().max_key().generation(),
        editor.state(),
    )?
    .expect("known query"))
}

fn find_pieces(editor: &Editor, search: &str) -> Result<Vec<Piece>, Error> {
    let reply = query_editor(editor, FIND, json!({ "search": search }))?;
    Ok(serde_json::from_value(reply["pieces"].clone())?)
}

fn replace(
    input: &Value,
    search: &str,
    replace_string: &str,
    pair: Option<u32>,
) -> Result<Value, Error> {
    let mut editor = editor(input)?;
    let pieces: Vec<_> = find_pieces(&editor, search)?
        .into_iter()
        .filter(|piece| pair.is_none_or(|pair| piece.pair_key == pair))
        .collect();
    let command = decode_command(
        REPLACE_NAME,
        &json!({"replaceString": replace_string, "once": pair.is_some(), "pieces": pieces})
            .to_string(),
        editor.state().max_key().generation(),
        None,
    )?
    .expect("replace command");
    let (handled, commit) = editor.dispatch(&command)?;
    assert_eq!(handled, Handled::Yes);
    // An ordinary update, as Source's editor.update: undoable, not historic.
    assert!(!commit.tags.contains(&UpdateTag::Historic));
    let view = editor.state().view();
    let selection = match view.selection() {
        Some(Selection::Node(nodes)) => {
            Value::from(nodes.keys().map(|key| path(view, key)).collect::<Vec<_>>())
        }
        _ => Value::Null,
    };
    Ok(json!({
        "children": serde_json::to_value(editor.state().to_json()?)?["root"]["children"],
        "nodeSelection": selection,
    }))
}

#[test]
fn replace_and_stats_match_the_source_oracle() -> Result<(), Error> {
    let oracle: serde_json::Map<String, Value> = serde_json::from_str(ORACLE)?;
    assert!(oracle.len() >= 10);
    for (name, case) in &oracle {
        let input = &case["input"];
        for replacement in case["replacements"].as_array().expect("replacements") {
            let query = replacement["query"].as_str().expect("query");
            let with = replacement["replaceString"].as_str().expect("replace");
            let all = replace(input, query, with, None)?;
            assert_eq!(
                all["children"], replacement["all"]["children"],
                "{name}: replace all {query:?}"
            );
            assert_eq!(all["nodeSelection"], replacement["all"]["nodeSelection"]);
            for once in replacement["once"].as_array().expect("once") {
                let pair = u32::try_from(once["pair"].as_u64().expect("pair")).expect("pair");
                let actual = replace(input, query, with, Some(pair))?;
                assert_eq!(
                    actual["children"], once["children"],
                    "{name}: replace {query:?} pair {pair}"
                );
                assert_eq!(
                    actual["nodeSelection"], once["nodeSelection"],
                    "{name}: replace {query:?} pair {pair} selection"
                );
            }
        }
        let editor = editor(input)?;
        let stats = query_editor(&editor, STATS_NAME, json!({}))?;
        assert_eq!(stats["text"], case["stats"]["text"], "{name}: stats text");
        assert_eq!(
            stats["progress"], case["stats"]["progress"],
            "{name}: progress"
        );
        assert_eq!(stats["selected"], Value::Null);
    }
    Ok(())
}

#[test]
fn replace_requests_must_be_objects() -> Result<(), Error> {
    assert!(decode_command(REPLACE_NAME, r#"["x", true, []]"#, 0, None).is_err());
    assert!(
        decode_command(
            REPLACE_NAME,
            r#"{"replaceString":"x","once":false,"pieces":[],"extra":1}"#,
            0,
            None
        )
        .is_err()
    );
    Ok(())
}

#[test]
fn replace_all_keeps_a_caret_past_the_shortened_text_inside_it() -> Result<(), Error> {
    let input = json!({"root": {
        "type":"root", "version":1, "direction":null, "format":"", "indent":0,
        "children":[{"type":"paragraph","version":1,"direction":null,"format":"","indent":0,
            "textFormat":0,"textStyle":"",
            "children":[{"type":"text","version":1,"text":"apple one Apple two apple",
                "detail":0,"format":0,"mode":"normal","style":""}]}]
    }});
    let mut editor = editor(&input)?;
    let text = editor
        .state()
        .view()
        .descendants(NodeKey::ROOT)
        .map(|(key, _)| key)
        .find(|key| editor.state().view().text(*key).is_some())
        .expect("text node");
    // The caret at the end of the text, as typing leaves it before Find.
    editor.update(|tx| {
        tx.set_selection(Some(Selection::Range(RangeSelection::collapsed(
            Point::text(text, Utf16Offset(25)),
        ))))
    })?;
    let pieces = find_pieces(&editor, "apple")?;
    let command = decode_command(
        REPLACE_NAME,
        &json!({"replaceString": "pear", "once": false, "pieces": pieces}).to_string(),
        editor.state().max_key().generation(),
        None,
    )?
    .expect("replace command");
    assert_eq!(editor.dispatch(&command)?.0, Handled::Yes);
    let view = editor.state().view();
    assert_eq!(view.text_content(text), "pear one pear two pear");
    let Some(Selection::Range(range)) = view.selection() else {
        panic!("range selection");
    };
    assert_eq!(range.anchor, Point::text(text, Utf16Offset(22)));
    assert_eq!(range.focus, Point::text(text, Utf16Offset(22)));
    editor.state().to_json()?;
    Ok(())
}

/// Source keeps an in-range numeric offset after Replace (setTextContent never
/// touches the selection); only a point past the new end is clamped.
fn replace_with_caret(offset: u32, once_pair: Option<u32>) -> Result<(String, Point), Error> {
    let input = json!({"root": {
        "type":"root", "version":1, "direction":null, "format":"", "indent":0,
        "children":[{"type":"paragraph","version":1,"direction":null,"format":"","indent":0,
            "textFormat":0,"textStyle":"",
            "children":[{"type":"text","version":1,"text":"apple one Apple two apple",
                "detail":0,"format":0,"mode":"normal","style":""}]}]
    }});
    let mut editor = editor(&input)?;
    let text = editor
        .state()
        .view()
        .descendants(NodeKey::ROOT)
        .map(|(key, _)| key)
        .find(|key| editor.state().view().text(*key).is_some())
        .expect("text node");
    editor.update(|tx| {
        tx.set_selection(Some(Selection::Range(RangeSelection::collapsed(
            Point::text(text, Utf16Offset(offset)),
        ))))
    })?;
    let pieces: Vec<_> = find_pieces(&editor, "apple")?
        .into_iter()
        .filter(|piece| once_pair.is_none_or(|pair| piece.pair_key == pair))
        .collect();
    let command = decode_command(
        REPLACE_NAME,
        &json!({"replaceString": "pear", "once": once_pair.is_some(), "pieces": pieces})
            .to_string(),
        editor.state().max_key().generation(),
        None,
    )?
    .expect("replace command");
    assert_eq!(editor.dispatch(&command)?.0, Handled::Yes);
    editor.state().to_json()?;
    let view = editor.state().view();
    let Some(Selection::Range(range)) = view.selection() else {
        panic!("range selection");
    };
    assert_eq!(range.anchor, range.focus);
    Ok((view.text_content(text).into_owned(), range.anchor))
}

#[test]
fn replace_keeps_an_in_range_caret_offset_and_clamps_only_past_the_end() -> Result<(), Error> {
    let (text, caret) = replace_with_caret(12, None)?;
    assert_eq!(text, "pear one pear two pear");
    assert_eq!(caret.offset(), 12);
    let (text, caret) = replace_with_caret(25, Some(3))?;
    assert_eq!(text, "apple one Apple two pear");
    assert_eq!(caret.offset(), 24);
    Ok(())
}
